import{_ as a,o as n,c as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"About Digital Employee Works","description":"","frontmatter":{},"headers":[],"relativePath":"en/about.md","filePath":"en/about.md","lastUpdated":1785829946000}'),t={name:"en/about.md"};function r(l,e,o,p,c,d){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="about-digital-employee-works" tabindex="-1">About Digital Employee Works <a class="header-anchor" href="#about-digital-employee-works" aria-label="Permalink to &quot;About Digital Employee Works&quot;">​</a></h1><p>Digital Employee Works is independently maintained by <strong>Zhu Wei (joinwell52-AI)</strong>. The Works continuously produces verifiable Digital Employee work and publishes its methods, Runtime specifications, work records, Observation Notes, and formal publications.</p><h2 id="current-digital-researcher" tabindex="-1">Current Digital Researcher <a class="header-anchor" href="#current-digital-researcher" aria-label="Permalink to &quot;Current Digital Researcher&quot;">​</a></h2><p>The current capability set is:</p><ul><li><strong>Research Report Production Engine V1.3</strong>;</li><li><strong>Research Runtime Center V4</strong>;</li><li><strong>Research Runtime Scheduler V2.0</strong>;</li><li><strong>Research Skills V2.0</strong>;</li><li><strong>Research Intelligence System V1.0</strong>.</li></ul><p>The Research Report Production Engine is a Research Analyst Digital Employee implemented through ChatGPT. It uses three intelligence pipelines to discover signals for three permanent columns, triage topics, advance research, produce complete bilingual reports, and release them through GitHub First.</p><h2 id="product-and-engineering-hierarchy" tabindex="-1">Product and engineering hierarchy <a class="header-anchor" href="#product-and-engineering-hierarchy" aria-label="Permalink to &quot;Product and engineering hierarchy&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA + FCoP</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>CodeFlowMu + Digital Employee</span></span></code></pre></div><ul><li><strong>TMPA:</strong> independent theory and specification layer;</li><li><strong>FCoP:</strong> file-based coordination protocol;</li><li><strong>CodeFlowMu:</strong> Digital Employee development and work Runtime;</li><li><strong>Digital Employee:</strong> product and delivery layer.</li></ul><p>The website capability section follows this hierarchy: TMPA and FCoP occupy the first row; CodeFlowMu leads the second row, followed by Digital Employee.</p><h2 id="three-research-columns" tabindex="-1">Three research columns <a class="header-anchor" href="#three-research-columns" aria-label="Permalink to &quot;Three research columns&quot;">​</a></h2><ul><li><strong>Digital Employee:</strong> position, responsibility, workflow, runtime, governance, and evaluation;</li><li><strong>Industry Architecture:</strong> the product and operating architecture of major AI platforms including OpenAI, Claude, Gemini, Cursor, GitHub Copilot, and Microsoft Copilot Platform;</li><li><strong>Open-source Engineering:</strong> agent runtimes, protocols, SDKs, tools, benchmarks, recovery, and observability engineering.</li></ul><h2 id="three-intelligence-pipelines" tabindex="-1">Three intelligence pipelines <a class="header-anchor" href="#three-intelligence-pipelines" aria-label="Permalink to &quot;Three intelligence pipelines&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI Platform Change Intelligence</span></span>
<span class="line"><span>GitHub Engineering Intelligence</span></span>
<span class="line"><span>Published Research Intelligence</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Unified signals and deduplication</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>Separate decisions for three columns</span></span></code></pre></div><h2 id="research-method" tabindex="-1">Research method <a class="header-anchor" href="#research-method" aria-label="Permalink to &quot;Research method&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Real sources and engineering</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Reconstructable evidence</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Governed research lifecycle</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Complete-report production</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>GitHub and website release</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Architecture, specifications, and public publication</span></span></code></pre></div><p>Observation Notes record academic, platform, and open-source developments encountered by the Digital Employee while working. They do not automatically become evidence for the TMPA paper.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><ul><li><a href="./publications/research-report-production-engine-v1.3">Research Report Production Engine V1.3</a></li><li><a href="./publications/research-report-production-engine-v1.3-quickstart">V1.3 Quick Start</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">Download the current source ZIP</a></li></ul>`,19)])])}const g=a(t,[["render",r]]);export{u as __pageData,g as default};
